ck_obligation_evidence_digest.value:
(
    "obligation_evidence"."provenance" = 'native' and length("obligation_evidence"."evidence_sha256") = 64
      and lower("obligation_evidence"."evidence_sha256") not glob '*[^0-9a-f]*'
  ) or (
    "obligation_evidence"."provenance" = 'legacy_v16' and ("obligation_evidence"."evidence_sha256" is null or (
      length("obligation_evidence"."evidence_sha256") = 64 and lower("obligation_evidence"."evidence_sha256") not glob '*[^0-9a-f]*'
    ))
  )

ck_obligation_schedules_next_cursor.value:
(
    "obligation_schedules"."next_occurrence_number" is null and "obligation_schedules"."next_occurrence_date" is null and "obligation_schedules"."next_materialization_date" is null
  ) or (
    "obligation_schedules"."next_occurrence_number" > 0 and "obligation_schedules"."next_occurrence_date" is not null and "obligation_schedules"."next_materialization_date" is not null
  )
